/**
 * Returns the authentic Modern Warfare 3 ADS animation clip for a specific weapon and fitted optic attachment.
 */
export function getOpticAdsClip(weaponId: string, attachmentId: string): THREE.AnimationClip | null {
  const normWeapon = weaponId.toLowerCase();
  const normAtt = attachmentId.toLowerCase();
  const mapping = WEAPON_OPTIC_MAP[normWeapon];
  if (!mapping) {
    return null;
  }
  let clipName = mapping[normAtt];
  if (!clipName) {
    for (const [k, v] of Object.entries(mapping)) {
      if (normAtt.includes(k) || k.includes(normAtt)) {
        clipName = v;
        break;
      }
    }
  }
  if (!clipName) {
    return null;
  }
  const data = OPTIC_ADS_CLIPS[clipName];
  if (!data) {
    return null;
  }
  const track = new THREE.VectorKeyframeTrack("tag_ads.position", data.times, data.values);
  const quatTrack = new THREE.QuaternionKeyframeTrack("tag_ads.quaternion", [0, data.duration], [0, 0, 0, 1, 0, 0, 0, 1]);
  return new THREE.AnimationClip(clipName, data.duration, [track, quatTrack]);
}
